const sportsGames=[
{id:181,type:"Baloncesto",categories:["Juegos motrices","Juegos con balón"],title:"Cazacanastas",cycle:"2.º ciclo",goals:["Bote","Percepción espacial"],material:"Balones",intensity:"Alta",duration:12,group:"Gran grupo",color:"orange",summary:"Cada participante bota su balón mientras busca una canasta libre para completar el reto indicado.",setup:"Distribuye al grupo por la pista con un balón por persona y utiliza todas las canastas disponibles.",rules:["Desplázate botando sin repetir dos veces seguidas la misma canasta.","A la señal, acércate a una canasta libre y lanza desde una marca adaptada.","Recoge tu balón y continúa; el reto común es alcanzar un número de aciertos."],variant:"Cambia la mano de bote o asigna distinta puntuación a cada zona de tiro.",observation:"Organiza turnos de entrada a la zona de lanzamiento para reducir esperas.",safety:"Cabeza levantada durante el bote y distancia entre lanzadores.",image:"images/games/181-baloncesto.webp"},
{id:182,type:"Baloncesto",categories:["Juegos motrices","Juegos cooperativos","Juegos con balón"],title:"Pases por puertas",cycle:"2.º ciclo",goals:["Pases","Desmarque"],material:"Balones",intensity:"Media",duration:12,group:"Parejas",color:"blue",summary:"Las parejas suman puntos pasando el balón a través de puertas de conos distribuidas por la pista.",setup:"Coloca muchas puertas de conos y entrega un balón por pareja.",rules:["El pase debe atravesar una puerta y ser recibido al otro lado.","Después de puntuar, busca una puerta diferente.","No se puede ocupar ni bloquear una puerta; gana el reto colectivo de pases."],variant:"Exige pase picado, de pecho o con la mano no dominante.",observation:"También puede jugarse por tríos con un defensor pasivo.",safety:"Puertas separadas y desplazamientos con visión periférica.",image:"images/games/181-baloncesto.webp"},
{id:183,type:"Baloncesto",categories:["Juegos motrices","Juegos cooperativos","Juegos con balón"],title:"Baloncesto sin aro",cycle:"1.º ciclo",goals:["Pases","Ocupación del espacio"],material:"Balones",intensity:"Media",duration:15,group:"2 equipos",color:"green",summary:"Iniciación al juego de invasión en la que se puntúa recibiendo dentro de una zona final.",setup:"Marca dos zonas de ensayo y forma equipos reducidos con un balón blando.",rules:["Se avanza mediante pases y quien tiene el balón permanece quieto.","Hay punto al recibir dentro de la zona contraria.","No se arrebata el balón de las manos ni existe contacto."],variant:"Permite un bote antes del pase o exige que todo el equipo toque el balón.",observation:"Prepara el desmarque y la conservación antes de introducir la canasta.",safety:"Campos pequeños separados y defensa a distancia de brazo.",image:"images/games/181-baloncesto.webp"},
{id:184,type:"Baloncesto",categories:["Juegos motrices","Juegos con balón"],title:"Las cuatro canastas",cycle:"3.º ciclo",goals:["Toma de decisiones","Lanzamientos"],material:"Balones",intensity:"Alta",duration:18,group:"2 equipos",color:"yellow",summary:"Dos equipos pueden atacar cualquiera de varias canastas y deben decidir rápidamente dónde crear ventaja.",setup:"Usa cuatro canastas o dos canastas y dos zonas de recepción como objetivos alternativos.",rules:["El equipo con balón puede puntuar en cualquier objetivo.","Después de cada punto, la posesión cambia sin sacar desde fondo.","No se puede atacar dos veces seguidas el mismo objetivo."],variant:"Otorga doble valor al objetivo más alejado de la recuperación.",observation:"Favorece amplitud, visión periférica y cambio de orientación.",safety:"Sin bloqueos en movimiento ni contacto corporal.",image:"images/games/181-baloncesto.webp"},
{id:185,type:"Baloncesto",categories:["Juegos motrices","Juegos cooperativos","Juegos con balón"],title:"Reloj de tiros",cycle:"2.º ciclo",goals:["Lanzamientos","Cooperación"],material:"Balones",intensity:"Media",duration:12,group:"Pequeños grupos",color:"orange",summary:"El equipo recorre posiciones alrededor de la canasta intentando completar conjuntamente la vuelta al reloj.",setup:"Marca seis posiciones de tiro asequibles alrededor de cada canasta.",rules:["Cada persona lanza desde la posición en la que está el equipo.","Un acierto permite avanzar a la siguiente marca.","El grupo intenta cerrar el reloj antes del tiempo límite."],variant:"Dos aciertos acumulados para avanzar o lanzamiento tras pase.",observation:"Ajusta las distancias para garantizar éxito frecuente.",safety:"Un único balón activo por canasta y recogida por los laterales.",image:"images/games/181-baloncesto.webp"},
{id:186,type:"Baloncesto",categories:["Juegos motrices","Juegos con balón"],title:"Tres contra dos continuo",cycle:"3.º ciclo",goals:["Superioridad numérica","Toma de decisiones"],material:"Balones",intensity:"Alta",duration:18,group:"Pequeños grupos",color:"blue",summary:"Ataques rápidos de tres contra dos que enlazan transición, ocupación de calles y finalización.",setup:"Sitúa dos defensores en cada media pista y una fila de atacantes en el centro.",rules:["Tres atacantes juegan contra dos defensores hasta lanzar o perder el balón.","Quien finaliza y sus dos compañeros pasan a defender en la otra mitad.","Entran tres nuevos atacantes y el juego continúa sin pausa."],variant:"Limita botes o exige un pase en cada calle antes de lanzar.",observation:"Detén brevemente para destacar decisiones, no solo velocidad.",safety:"Evita entradas con contacto y deja despejada la zona bajo canasta.",image:"images/games/181-baloncesto.webp"},

{id:187,type:"Fútbol",categories:["Juegos motrices","Juegos con balón"],title:"Semáforo con balón",cycle:"1.º ciclo",goals:["Conducción","Control"],material:"Balones",intensity:"Media",duration:10,group:"Individual",color:"green",summary:"Conducir el balón adaptando velocidad y acción a distintas señales de color.",setup:"Cada participante dispone de balón en un espacio delimitado y sin porterías.",rules:["Verde: conduce; amarillo: toques cortos; rojo: pisa y detén el balón.","Azul indica cambio de pie y blanco, giro y salida.","Nadie queda eliminado si se equivoca."],variant:"Una persona del alumnado dirige las señales.",observation:"Empieza caminando y amplía el espacio antes de aumentar la velocidad.",safety:"Balón siempre cerca y prohibidos los golpeos largos.",image:"images/games/187-futbol.webp"},
{id:188,type:"Fútbol",categories:["Juegos motrices","Juegos con balón"],title:"Limpia tu campo con los pies",cycle:"2.º ciclo",goals:["Golpeo","Orientación"],material:"Balones",intensity:"Alta",duration:10,group:"2 equipos",color:"orange",summary:"Cada equipo intenta dejar su mitad sin balones enviándolos rasos al campo contrario.",setup:"Divide la pista y reparte el mismo número de balones blandos en ambas mitades.",rules:["A la señal, golpea un solo balón cada vez hacia el otro campo.","Los balones deben viajar rasos y nadie puede cruzar la línea central.","Al detener la señal, se cuentan los balones de cada campo."],variant:"Conduce primero hasta una línea de golpeo o utiliza solo el pie no dominante.",observation:"Rondas breves de treinta a cuarenta segundos.",safety:"Balones blandos, tiros rasos y sin porteros junto a la línea central.",image:"images/games/187-futbol.webp"},
{id:189,type:"Fútbol",categories:["Juegos motrices","Juegos cooperativos","Juegos con balón"],title:"Fútbol por zonas",cycle:"3.º ciclo",goals:["Pases","Ocupación del espacio"],material:"Balones",intensity:"Alta",duration:18,group:"2 equipos",color:"blue",summary:"Partido reducido dividido en franjas para favorecer apoyos, amplitud y progresión mediante pases.",setup:"Divide el campo en tres zonas y forma dos equipos pequeños sin portero.",rules:["Debe haber al menos una persona del equipo en cada zona.","El balón avanza a la zona siguiente mediante pase.","Se marca en miniportería y después saca el otro equipo."],variant:"Permite que quien pasa avance de zona o limita los toques.",observation:"Las zonas son una ayuda temporal y pueden retirarse progresivamente.",safety:"Sin entradas al suelo ni contacto; miniporterías estables.",image:"images/games/187-futbol.webp"},
{id:190,type:"Fútbol",categories:["Juegos motrices","Juegos cooperativos","Juegos con balón"],title:"El rondo viajero",cycle:"2.º ciclo",goals:["Pases","Apoyo"],material:"Balones",intensity:"Media",duration:12,group:"Pequeños grupos",color:"yellow",summary:"El grupo conserva el balón y cambia de cuadrado al alcanzar una secuencia de pases.",setup:"Marca varios cuadrados cercanos y organiza grupos de cinco con un defensor.",rules:["Cuatro atacantes conservan ante un defensor.","Tras cinco pases, todo el grupo viaja al cuadrado libre manteniendo la posesión.","Si el defensor recupera, intercambia su función con quien perdió el balón."],variant:"Dos defensores o máximo de dos toques.",observation:"Prioriza líneas de pase y movilidad sobre la rapidez del balón.",safety:"Cuadrados separados y sin entradas fuertes.",image:"images/games/187-futbol.webp"},
{id:191,type:"Fútbol",categories:["Juegos motrices","Juegos con balón"],title:"Derriba-conos con el pie",cycle:"1.º ciclo",goals:["Precisión","Golpeo"],material:"Balones",intensity:"Media",duration:12,group:"Parejas",color:"orange",summary:"Las parejas realizan pases rasos intentando derribar conos colocados entre ambas.",setup:"Cada pareja se coloca frente a frente con tres conos centrales y un balón blando.",rules:["Golpea raso desde detrás de la línea.","Cada cono derribado suma uno y se vuelve a colocar.","Alterna el pie de golpeo y la función de recogida."],variant:"Cambia la distancia o asigna distinto valor a cada cono.",observation:"Puede hacerse cooperativo contando derribos entre todas las parejas.",safety:"Todas las parejas orientadas en la misma dirección y recogida tras señal.",image:"images/games/187-futbol.webp"},
{id:192,type:"Fútbol",categories:["Juegos motrices","Juegos con balón"],title:"Partido de cuatro porterías",cycle:"3.º ciclo",goals:["Toma de decisiones","Cambio de orientación"],material:"Balones",intensity:"Alta",duration:18,group:"2 equipos",color:"green",summary:"Cada equipo defiende dos miniporterías y puede atacar dos objetivos opuestos.",setup:"Coloca una miniportería en cada esquina de un campo ancho y forma equipos de cuatro o cinco.",rules:["Cada equipo ataca las dos porterías del fondo contrario.","Tras recuperar, debe realizar al menos un pase antes de marcar.","No hay porteros ni se permite bloquear una portería permaneciendo delante."],variant:"Todas las porterías son atacables y el punto cambia la posesión.",observation:"Estimula levantar la cabeza y cambiar el lado de ataque.",safety:"Sin entradas al suelo; porterías ancladas o de conos.",image:"images/games/187-futbol.webp"},

{id:193,type:"Hockey",categories:["Juegos motrices"],title:"El bosque de sticks",cycle:"2.º ciclo",goals:["Conducción","Coordinación"],material:"Sticks",intensity:"Media",duration:12,group:"Individual",color:"green",summary:"Conducción controlada entre conos con cambios de dirección y paradas seguras.",setup:"Prepara recorridos amplios de conos y entrega stick y pelota ligera a cada participante.",rules:["Conduce pasando por todos los árboles sin tocarlos.","Detén la pelota en cada claro señalado.","Regresa por un recorrido diferente manteniendo la pala baja."],variant:"Cambia de lado de la pala o sigue a un compañero guía.",observation:"Practica primero agarre, postura y parada de la pelota.",safety:"Stick siempre por debajo de la rodilla y distancia amplia.",image:"images/games/193-hockey.webp"},
{id:194,type:"Hockey",categories:["Juegos motrices","Juegos cooperativos"],title:"Pases por portillos de hockey",cycle:"2.º ciclo",goals:["Pases","Recepción"],material:"Sticks",intensity:"Media",duration:12,group:"Parejas",color:"blue",summary:"Las parejas enlazan pases de hockey a través de pequeñas puertas de conos.",setup:"Distribuye portillos por la pista con pelota y dos sticks por pareja.",rules:["La pelota debe atravesar el portillo a ras de suelo.","Recibe, controla y busca otro portillo libre.","No se golpea de primera ni se repite puerta."],variant:"Tríos con desplazamiento triangular o puntos por puertas de colores.",observation:"Trabaja acompañamiento de la pelota antes que potencia.",safety:"Pala baja, pases suaves y sin invadir el recorrido de otra pareja.",image:"images/games/193-hockey.webp"},
{id:195,type:"Hockey",categories:["Juegos motrices"],title:"Hockey-golf escolar",cycle:"2.º ciclo",goals:["Precisión","Dosificación de fuerza"],material:"Sticks",intensity:"Baja",duration:15,group:"Pequeños grupos",color:"yellow",summary:"Completar un recorrido de hoyos enviando la pelota hacia aros o puertas con el menor número de golpes controlados.",setup:"Diseña hoyos seguros con conos, aros planos y curvas amplias.",rules:["Golpea desde donde se detuvo la pelota.","Anota los golpes, pero espera a que la zona esté libre.","Completa el recorrido respetando el sentido marcado."],variant:"Resultado cooperativo sumando un máximo de golpes para todo el grupo.",observation:"Adecuado para control técnico y vuelta a la calma específica.",safety:"Una persona golpea cada vez y el resto espera detrás.",image:"images/games/193-hockey.webp"},
{id:196,type:"Hockey",categories:["Juegos motrices","Juegos con balón"],title:"Conquista las esquinas con stick",cycle:"3.º ciclo",goals:["Conducción","Toma de decisiones"],material:"Sticks",intensity:"Alta",duration:15,group:"2 equipos",color:"orange",summary:"Juego de invasión en el que se puntúa controlando la pelota dentro de una de las dos esquinas rivales.",setup:"Marca cuatro zonas de puntuación, dos para cada equipo, y juega en grupos reducidos.",rules:["Se avanza conduciendo o pasando a ras de suelo.","Hay punto si la pelota queda controlada dentro de una esquina rival.","Después del punto saca el otro equipo desde el centro."],variant:"Anula temporalmente la esquina donde se acaba de puntuar.",observation:"Ofrece dos objetivos para favorecer lectura del espacio.",safety:"Sin contacto, sin levantar stick ni pelota y defensa a distancia.",image:"images/games/193-hockey.webp"},
{id:197,type:"Hockey",categories:["Juegos motrices","Juegos cooperativos"],title:"Rondo de hockey",cycle:"3.º ciclo",goals:["Pases","Apoyo"],material:"Sticks",intensity:"Media",duration:12,group:"Pequeños grupos",color:"green",summary:"Conservación de pelota con sticks en un espacio reducido y oposición progresiva.",setup:"Organiza cuadrados con cuatro atacantes exteriores y un defensor interior.",rules:["Los atacantes pasan a ras de suelo sin entrar en el cuadrado.","El defensor intercepta solo con la pala y sin contacto.","Si recupera o la pelota sale, cambia con quien realizó el último pase."],variant:"Dos defensores o pase obligatorio al lado opuesto.",observation:"Empieza con defensor pasivo para afianzar control y recepción.",safety:"Sticks bajos y prohibido golpear cerca de pies ajenos.",image:"images/games/193-hockey.webp"},
{id:198,type:"Hockey",categories:["Juegos motrices"],title:"Hockey a cuatro porterías",cycle:"3.º ciclo",goals:["Juego colectivo","Cambio de orientación"],material:"Sticks",intensity:"Alta",duration:18,group:"2 equipos",color:"blue",summary:"Partido reducido con dos porterías por equipo que multiplica las opciones de ataque.",setup:"Sitúa miniporterías de conos en las esquinas y forma equipos de cuatro.",rules:["Cada equipo ataca las dos porterías contrarias.","El gol solo vale con tiro raso desde fuera de una zona de seguridad.","No hay porteros y nadie puede quedarse fijo tapando una portería."],variant:"Marca después de tres pases o utiliza una portería de cada color.",observation:"Favorece amplitud y circulación frente a la acumulación.",safety:"Pelota blanda, tiro raso, sticks bajos y sin contacto.",image:"images/games/193-hockey.webp"},

{id:199,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"Museo de emociones",cycle:"1.º ciclo",goals:["Expresión corporal","Emociones"],material:"Sin material",intensity:"Baja",duration:10,group:"Pequeños grupos",color:"blue",summary:"Un museo vivo en el que las estatuas representan emociones y cobran movimiento cuando llega una visita.",setup:"Distribuye pequeños grupos por zonas; una persona de cada grupo comienza como visitante.",rules:["Las estatuas adoptan una postura relacionada con una emoción.","La visita recorre el museo y toca suavemente una estatua para verla moverse.","Después intenta identificar la emoción y se cambian los papeles."],variant:"Representa emociones mezcladas o cambios de intensidad.",observation:"Acepta interpretaciones diferentes y pide explicar las señales corporales.",safety:"Posturas estables, espacio personal y sin contacto salvo el toque acordado.",image:"images/games/199-expresion-corporal.webp"},
{id:200,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"La máquina fantástica",cycle:"2.º ciclo",goals:["Ritmo","Creación colectiva"],material:"Sin material",intensity:"Media",duration:12,group:"Equipos de 6",color:"green",summary:"Cada integrante añade un movimiento y un sonido hasta construir una máquina colectiva coordinada.",setup:"Forma grupos separados y deja un espacio de creación para cada uno.",rules:["Entra una persona con un movimiento repetido y un sonido.","Las demás se incorporan una a una conectando su acción con la máquina.","Cuando está completa, cambia velocidad, volumen o función imaginaria."],variant:"Máquinas de reciclar, viajar, fabricar música o resolver problemas.",observation:"La creación debe permitir que todas las aportaciones sean visibles.",safety:"Movimientos controlados y conexiones sin cargar peso.",image:"images/games/199-expresion-corporal.webp"},
{id:201,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"Historias en tres escenas",cycle:"3.º ciclo",goals:["Dramatización","Secuenciación"],material:"Sin material",intensity:"Baja",duration:18,group:"Equipos de 5",color:"orange",summary:"Crear una pequeña historia con planteamiento, problema y solución mediante tres imágenes corporales.",setup:"Entrega a cada grupo un lugar, un personaje y un objeto imaginario.",rules:["Diseña tres estatuas colectivas que cuenten la historia.","Muestra cada imagen durante cinco segundos y enlázala con una transición.","El público interpreta lo sucedido antes de escuchar la explicación."],variant:"Añade narrador, cámara lenta o un final alternativo.",observation:"Valora claridad corporal, cooperación y coherencia, no calidad teatral.",safety:"Figuras a baja altura y sin apoyarse sobre otras personas.",image:"images/games/199-expresion-corporal.webp"},
{id:202,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"Sombras que cobran vida",cycle:"1.º ciclo",goals:["Imitación","Creatividad"],material:"Sin material",intensity:"Baja",duration:10,group:"Parejas",color:"yellow",summary:"Una persona crea movimientos expresivos y su sombra los sigue, transformándolos poco a poco.",setup:"Distribuye parejas con distancia suficiente y elige guía y sombra.",rules:["La guía se mueve despacio y la sombra imita detrás.","A la señal, la sombra propone una pequeña transformación del movimiento.","Cambian roles sin detener la secuencia."],variant:"Sombras de animales, gigantes, robots o personajes sorprendidos.",observation:"Diferente del espejo: ambas personas miran en la misma dirección.",safety:"Desplazamientos suaves y sin movimientos bruscos hacia atrás.",image:"images/games/199-expresion-corporal.webp"},
{id:203,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"El objeto imaginario",cycle:"2.º ciclo",goals:["Mimo","Creatividad"],material:"Sin material",intensity:"Baja",duration:12,group:"Gran grupo",color:"blue",summary:"Un objeto invisible pasa de mano en mano cambiando su peso, tamaño, temperatura y utilidad.",setup:"Forma un círculo amplio con todo el grupo.",rules:["La primera persona manipula un objeto imaginario y lo entrega.","Quien lo recibe respeta sus características antes de transformarlo.","El grupo intenta adivinar cada nueva función sin hablar durante la acción."],variant:"Mantén siempre el mismo objeto dentro de una escena compartida.",observation:"Trabaja mirada, tensión muscular, precisión gestual y relación con el espacio.",safety:"Gestos amplios sin invadir a quienes están al lado.",image:"images/games/199-expresion-corporal.webp"},
{id:204,type:"Dramatización y expresión corporal",categories:["Juegos cooperativos"],title:"Doblaje corporal",cycle:"3.º ciclo",goals:["Dramatización","Coordinación expresiva"],material:"Sin material",intensity:"Baja",duration:15,group:"Parejas",color:"green",summary:"Una persona interpreta corporalmente una escena mientras su pareja pone voz, sonidos y narración.",setup:"Forma parejas y prepara situaciones breves: una tormenta, una expedición o un día disparatado.",rules:["La persona intérprete actúa sin hablar.","La dobladora aporta voz y efectos siguiendo con atención los gestos.","Después cambian funciones y representan una situación nueva."],variant:"Dos parejas comparten escena o cambian de género: aventura, misterio o comedia.",observation:"Deja un minuto de preparación y limita cada escena para mantener ritmo.",safety:"Sin imitaciones ofensivas, contacto físico ni acciones peligrosas.",image:"images/games/199-expresion-corporal.webp"}
];
